// Exports the OpenAPI document of every running service to docs/api/.
//
//   npm run openapi:export
//
// The documents are generated by the services themselves (from their route
// and validation definitions), fetched through the API gateway. The contract
// test tests/contract/api-contract.test.ts fails when the committed documents
// no longer match the running services, so an API cannot change silently.
import { mkdirSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { rawApi } from './lib/titan-client.mjs';

export const API_SERVICES = ['tenant', 'case', 'workflow', 'notification', 'audit', 'asset', 'device', 'telemetry', 'alert', 'incident', 'analytics', 'pipeline', 'ai'];
export const API_DIR = fileURLToPath(new URL('../docs/api', import.meta.url));

/** Stable form of an OpenAPI document: sorted keys, so diffs show real changes only. */
export function normalise(value) {
  if (Array.isArray(value)) return value.map(normalise);
  if (value && typeof value === 'object') return Object.fromEntries(Object.keys(value).sort().map((k) => [k, normalise(value[k])]));
  return value;
}

export async function fetchSpec(key) {
  const res = await rawApi('adam.admin', 'GET', `/api/${key}/docs-json`);
  return res.status === 200 && res.body?.paths ? normalise(res.body) : null;
}

export function operations(spec) {
  const out = [];
  for (const [route, methods] of Object.entries(spec.paths ?? {})) {
    for (const method of Object.keys(methods)) {
      if (['get', 'post', 'put', 'patch', 'delete'].includes(method)) out.push(`${method.toUpperCase()} ${route}`);
    }
  }
  return out.sort();
}

if (process.argv[1] && fileURLToPath(import.meta.url) === path.resolve(process.argv[1])) {
  mkdirSync(API_DIR, { recursive: true });
  const index = [];
  for (const key of API_SERVICES) {
    const spec = await fetchSpec(key);
    if (!spec) {
      console.log(`  - ${key}: not running, skipped`);
      continue;
    }
    writeFileSync(path.join(API_DIR, `${key}.openapi.json`), `${JSON.stringify(spec, null, 2)}\n`);
    const ops = operations(spec);
    index.push({ key, title: spec.info?.title ?? key, description: spec.info?.description ?? '', operations: ops });
    console.log(`  + ${key}: ${ops.length} operations`);
  }
  const lines = [
    '# API specifications',
    '',
    'Generated by `npm run openapi:export` from the running services. Do not edit by hand.',
    '',
    'All routes are reached through the API gateway as `/api/<key>/<path>` and require a bearer token',
    'issued by Keycloak. Every service also serves its interactive documentation at `/api/<key>/docs`.',
    '',
    'Errors use one shape: `{ "error": { "status", "code", "message", "details?", "correlation_id" } }`.',
    '',
    ...index.flatMap((s) => [
      `## ${s.title} (\`/api/${s.key}\`)`,
      '',
      s.description,
      '',
      `Specification: [${s.key}.openapi.json](${s.key}.openapi.json)`,
      '',
      '| Method | Path |',
      '| --- | --- |',
      ...s.operations.map((o) => `| ${o.split(' ')[0]} | \`/api/${s.key}${o.split(' ')[1]}\` |`),
      '',
    ]),
  ];
  writeFileSync(path.join(API_DIR, 'README.md'), `${lines.join('\n')}\n`);
  console.log(`Wrote ${index.length} specifications to docs/api/`);
}
